        if d(i).Biasvalue(c) == 7 || d(i).Biasvalue(c) == 9 || d(i).Biasvalue(c) == 10 
            AnyIHCLackofBlind(i,c) = d(i).effectVal(c);
        else
            AnyIHCLackofBlind(i,c) = NaN;
        end
    end
end
MeanAnyIHCLackBlind = mean(AnyIHCLackofBlind,  2, 'omitnan'); %12 articles sum(~isnan(MeanAnyIHCLackBlind))
MeanMeanAnyIHCLackBlind = mean(MeanAnyIHCLackBlind, 'omitnan');
STDMeanAnyIHCLackBlind  = std(MeanAnyIHCLackBlind, 'omitnan');
[LMeanAnyIHCLackBlind UMeanAnyIHCLackBlind] = bounds(MeanAnyIHCLackBlind);



