%kinetic energy and newtons calculation based on mychasiuk equations from
%mychasiuk et al 2016 the direction of the association and rotational
%forces associated with mild traumatic brain injury in rodents effect
%behavioral and molecular outcomes
% kinetic energy (KE)  = mass (kg) * g (gravitational acceleration) * h (height
% in meters)
% Force = KE/ D (d = distance in which weight came to a stop)
%
% Also doing the equation force in a vacuum
%




%papers with no effects check
clear i
clear c
for i = 1:length(d)
    for c = 1:length(d(i).effectVal)
        %if contains(d(i).comp(c), ["TBI vs SHAM" "injury vs Sham" "hit vs Sham" "injury group vs sham" "TBI injured progressed vs SHAM"], 'ignorecase', true) == 1
        d(i).EffectValNaN(c) = isnan(d(i).effectVal(c)); %if the value is a NaN, then it will be a 1. below I check if the mean of this value is 1, which means a paper had no effect values.
        %else
        %    d(i).EffectValNaN(c) = NaN;
        %end
    end
end

clear i
clear c
for i = 1:length(d)
        d(i).PercentofMainEffectsCalc = (1-mean(d(i).EffectValNaN))*100;
end

clear i
clear c
for i = 1:length(d)
    for c = 1:length(d(i).rightTimeEffect)
        d(i).RighttimeEffectValNaN(c) = isnan(d(i).rightTimeEffect(c));
    end
end
clear i
for i = 1:length(d)
    if mean(d(i).EffectValNaN) == 1
        d(i).NoMainEffectVals = 1;
    else
        d(i).NoMainEffectVals = 0;
    end
end

clear i
for i = 1:length(d)
    if mean(d(i).RighttimeEffectValNaN) == 1
        d(i).NoRightingEffectVals = 1;
    else
        d(i).NoRightingEffectVals = 0;
    end
end

for i = 1:length(d)
    if mean([d(i).NoMainEffectVals d(i).NoRightingEffectVals]) == 1
        d(i).overallEffects = 1;
    else
        d(i).overallEffects = 0;
    end
end

for i = 1:length(d)
    papersWith_noeffects(i) = d(i).overallEffects;
end

clear i
clear c
for i = 1:length(d)
    for c = 1:length(d(i).hitCount)
        if d(i).hitCount(c) >1 || length(d(i).hitCount) >1
            hitCountCounter(i) = 1; 
        else
            SinglehitCounter(i) = 1;


        end
    end
end



clear i
clear c %does not work with brain regions
for i = 1:length(d)
    for c = 1:length(d(i).task_or_stain)
        if d(i).overallEffects == 1
            d(i).FullCompStatement(c) = "paper had no effects";
        elseif d(i).overallEffects == 0 %zero means there were effects based on code directly above
            d(i).FullCompStatement(c) = join([d(i).task_or_stain(c) d(i).comp(c) d(i).comp_direction(c) num2str(d(i).effectVal(c))], ',');
        
        end

    end
end


clear i
clear c
for i = 1:length(d)
    for c  = 1:length(d(i).task_or_stain)
        if d(i).NoMainEffectVals == 0
            if d(i).EffectValNaN(c) == 0
            ["task", i, c, d(i).task_or_stain(c), d(i).comp(c), d(i).comp_direction(c), d(i).effectVal(c), d(i).task_or_stainCat(c)];
            ["task", d(i).ModelStat, d(i).Species, d(i).comp(c), d(i).comp_direction(c), d(i).effectVal(c), d(i).task_or_stainCat(c)];
            %[d(i).task_or_stain(c) d(i).task_or_stainCat(c)]
           % keyboard
            
            end
        end
    end
end


clear i
clear c
for i = 1:length(d)
    for c  = 1:length(d(i).rightTimeEffect)
        if d(i).NoMainEffectVals == 0
            if d(i).RighttimeEffectValNaN(c) == 0
            ["righting", i, c, d(i).rightTimeDir(c), d(i).rightTimeEffect(c)];
            
            end
        end
    end
end


