clear i  
clear c
for i = 1:length(d)
    for c = 1:length(d(i).task_or_stain)
        if d(i).NoMainEffectVals == 0
            if d(i).EffectValNaN(c) == 0
                if d(i).task_or_stainCat(c) == 1
                    if d(i).ModelStat == 1 && d(i).Species == 1 
                        OFTRFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 1 && d(i).Species == 0 
                        OFTMFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 1 
                        OFTRFS(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 0
                        OFTMFS(i,c) = d(i).effectVal(c);
                    end

                elseif d(i).task_or_stainCat(c) == 2 
                    if d(i).ModelStat == 1 && d(i).Species == 1 % && contains(d(i).comp(c), "time spent in novel/closed arm percentage" , 'ignorecase', true) == 1
                        YMazeRFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 1 && d(i).Species == 0 % && contains(d(i).comp(c), "time spent in novel/closed arm percentage" , 'ignorecase', true) == 1
                        YMazeMFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 1 % && contains(d(i).comp(c), "time spent in novel/closed arm percentage" , 'ignorecase', true) == 1
                        YMazeRFS(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 0 % && contains(d(i).comp(c), "time spent in novel/closed arm percentage" , 'ignorecase', true) == 1
                        YMazeMFS(i,c) = d(i).effectVal(c);
                    end
                    

                elseif d(i).task_or_stainCat(c) == 3 
                    if d(i).ModelStat == 1 && d(i).Species == 1 % && contains(d(i).comp(c), "preference index" , 'ignorecase', true) == 1
                        NORRFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 1 && d(i).Species == 0 % && contains(d(i).comp(c), "preference index" , 'ignorecase', true) == 1
                        NORMFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 1 % && contains(d(i).comp(c), "preference index" , 'ignorecase', true) == 1
                        NORRFS(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 0 % && contains(d(i).comp(c), "preference index" , 'ignorecase', true) == 1
                        NORMFS(i,c) = d(i).effectVal(c);
                    end
                    

                elseif d(i).task_or_stainCat(c) == 4 
                    if d(i).ModelStat == 1 && d(i).Species == 1 % && contains(d(i).comp(c), "percent time in open arm" , 'ignorecase', true) == 1
                        EPMRFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 1 && d(i).Species == 0 % && contains(d(i).comp(c), "percent time in open arm" , 'ignorecase', true) == 1
                        EPMMFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 1 % && contains(d(i).comp(c), "percent time in open arm" , 'ignorecase', true) == 1
                        EPMRFS(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 0 % && contains(d(i).comp(c), "percent time in open arm" , 'ignorecase', true) == 1
                        EPMMFS(i,c) = d(i).effectVal(c);
                    end
                    
                elseif d(i).task_or_stainCat(c) == 5 
                    if d(i).ModelStat == 1 && d(i).Species == 1 % && contains(d(i).comp(c), ["distance travelled" "distance traveled"] , 'ignorecase', true) == 1
                        LocomotorActRFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 1 && d(i).Species == 0 % && contains(d(i).comp(c), ["distance travelled" "distance traveled"] , 'ignorecase', true) == 1
                        LocomotorActMFF(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 1 % && contains(d(i).comp(c), ["distance travelled" "distance traveled"] , 'ignorecase', true) == 1
                        LocomotorActRFS(i,c) = d(i).effectVal(c);
                    elseif d(i).ModelStat == 0 && d(i).Species == 0 % && contains(d(i).comp(c), ["distance travelled" "distance traveled"] , 'ignorecase', true) == 1
                        LocomotorActMFS(i,c) = d(i).effectVal(c);
                    end
                    %keep building out based on measures

                elseif d(i).task_or_stainCat(c) == 6 
