clear i 
clear c
for i = 1:length(d)
    if contains(d(i).impactorChar, "na", 'ignorecase', true) == 1
        ImpactCharNotExists(i) = 1;
    else
        ImpactCharExists(i) = 1;
    end
end


clear i
clear c
for i = 1:length(d)
    if d(i).Helmetstat == 1 && matches(d(i).helmetChar, ["na" "not described"], 'ignorecase', true) == 1 || d(i).Helmetstat == 2 && matches(d(i).helmetChar,["na" "not described"], 'ignorecase', true) == 1
       HelmetCharNotDescribed(i) = 1;
    elseif d(i).Helmetstat == 1 && matches(d(i).helmetChar, ["metal disc" "metallic disc" "steel disc (not described)" "steel disc" "metallic helmet" "metal disc not described further" "metal helmet"], 'ignorecase', true) == 1 || d(i).Helmetstat == 2 && matches(d(i).helmetChar,["metal disc" "metallic disc" "steel disc (not described)" "steel disc" "metallic helmet" "metal disc not described further" "metal helmet"], 'ignorecase', true) == 1
       HelmetCharVague(i) = 1;
    elseif d(i).Helmetstat == 1 || d(i).Helmetstat == 2
       HelmetCharGiven(i) = 1;
        
    end
end

clear i 
clear c
for i = 1:length(d)
    if d(i).ModelStat == 0 && contains(d(i).Mar_likePlatform, ["na"], 'ignorecase', true) == 1
        FixedSurfNotDesc(i) = 1;
    elseif d(i).ModelStat == 0 && contains(d(i).Mar_likePlatform, ["foam" "sponge" ], 'ignorecase', true) == 1
        FixedSurfaceCushion(i) = 1;
    elseif d(i).ModelStat == 0 && contains(d(i).Mar_likePlatform, [ "vice" "rubber"  "rigid" "stereotax" "wooden plate" "fixed on bottom of platform" "secured on the animal holder" ], 'ignorecase', true) == 1
        FixedSurfaceHardImmobile(i) = 1;
    end
end


clear i
clear c
for i = 1:length(d)
    d(i).ParsedFreeFall = split(d(i).freeFallplatform, ',');
end

clear i
clear c
for i = 1:length(d)
    for c = 1:length(d(i).ParsedFreeFall)
        if d(i).ModelStat == 1 && contains(d(i).ParsedFreeFall(c), ["not describe" "na"], 'ignorecase', true) == 1
            d(i).ParsedBooleanFreeFallPlat(c) = 0;
        elseif d(i).ModelStat == 1
            d(i).ParsedBooleanFreeFallPlat(c) = 1;
        elseif d(i).ModelStat == 0
            d(i).ParsedBooleanFreeFallPlat(c) = NaN;
        end
        if length(d(i).ParsedFreeFall) > 1
            if d(i).ModelStat == 1 && contains(d(i).ParsedFreeFall(3), ["secured by tail so does not come to a stop on a piece of foam" ], 'ignorecase', true) == 1
                d(i).ParsedBooleanFreeFallPlat(4) = NaN; %this version of the model does not have a landing platform
                d(i).ParsedBooleanFreeFallPlat(1) = NaN; %nor does this version of the model does not have a measureable fall height because it is basically the tail length relative to grasping position
            end
        end
    end
end

for i = 1:length(d)
d(i).ProportionofFreeFallInfo = mean(d(i).ParsedBooleanFreeFallPlat, 'omitnan');
end

for i = 1:length(d)
    for c = 1:length(d(i).ParsedBooleanFreeFallPlat)
        if d(i).ModelStat == 1 && d(i).ProportionofFreeFallInfo == 1
             TotalFreeFallInfoGiven(i) = 1;
        elseif d(i).ModelStat == 1 && d(i).ProportionofFreeFallInfo == 0.75
             ThreeQuartFreeFallInfoGiven(i) = 1;
        elseif d(i).ModelStat == 1 && d(i).ProportionofFreeFallInfo == 0.5
             HalfFreeFallInfoGiven(i) = 1;
        elseif d(i).ModelStat == 1 && d(i).ProportionofFreeFallInfo == 0.25
             QuarterFreeFallInfoGiven(i) = 1;
         elseif d(i).ModelStat == 1 && d(i).ProportionofFreeFallInfo == 0
             NoneFreeFallInfoGiven(i) = 1;

        end
    end
end


